leetcode-167-two-sum-ii.answer:
def pair_sum(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        # ① COMBINE the two boundary values
        s = nums[left] + nums[right]
        # ② CHECK against target
        if s == target:
            return [left + 1, right + 1]  # ③ RETURN 1-indexed positions
        elif s < target:
            left += 1  # ④ MOVE left inward, sum too small
        else:
            right -= 1  # ⑤ MOVE right inward, sum too large
    return []  # ⑥ no pair found

