leetcode-125-valid-palindrome.answer:
def is_palindrome(s):
    left, right = 0, len(s) - 1
    while left < right:
        if not s[left].isalnum():
            left += 1
            continue
        if not s[right].isalnum():
            right -= 1
            continue
        if s[left].lower() != s[right].lower():
            return False
        left += 1
        right -= 1
    return True

leetcode-15-3sum.answer:
def three_sum(nums):
    nums.sort()  # ① SORT so duplicates are adjacent and two pointers work
    result = []
    for i in range(len(nums) - 2):
        # ② SKIP duplicate first elements
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, len(nums) - 1
        # ③ TWO POINTERS on the remaining slice
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                result.append([nums[i], nums[left], nums[right]])  # ④ RECORD triplet
                # ⑤ SKIP duplicate values on both sides
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < 0:
                left += 1  # ⑥ MOVE left inward, sum too small
            else:
                right -= 1  # ⑦ MOVE right inward, sum too large
    return result

