leetcode-26-remove-duplicates-from-sorte.answer:
def remove_duplicates(nums):
    if not nums:
        return 0
    slow = 0
    # ① FAST scans ahead for a new value
    for fast in range(1, len(nums)):
        # ② CHECK if this value differs from the last kept one
        if nums[fast] != nums[slow]:
            slow += 1  # ③ ADVANCE write pointer
            nums[slow] = nums[fast]  # ④ WRITE new unique value
    return slow + 1  # ⑤ count of unique elements

