leetcode-75-sort-colors.answer:
def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    # ① SCAN with mid until it passes high
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]  # ② SWAP 0 to the low region
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1  # ③ 1 already in place
        else:
            nums[mid], nums[high] = nums[high], nums[mid]  # ④ SWAP 2 to the high region
            high -= 1  # note: mid not advanced, must recheck swapped-in value
    return nums

