leetcode-215-kth-largest-element-in-an-a.answer:
import random

def find_kth_largest(nums, k):
    target = len(nums) - k  # ① index of kth largest in sorted order

    def partition(left, right):
        pivot_index = random.randint(left, right)  # ② PICK random pivot
        pivot = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]  # move pivot to end
        store = left
        # ③ CLASSIFY elements smaller than pivot to the front
        for i in range(left, right):
            if nums[i] < pivot:
                nums[i], nums[store] = nums[store], nums[i]
                store += 1
        nums[store], nums[right] = nums[right], nums[store]  # ④ PLACE pivot at final position
        return store

    left, right = 0, len(nums) - 1
    while True:
        pivot_index = partition(left, right)
        # ⑤ CHECK if pivot landed at target rank
        if pivot_index == target:
            return nums[pivot_index]
        elif pivot_index < target:
            left = pivot_index + 1  # ⑥ RECURSE into right side only
        else:
            right = pivot_index - 1  # ⑦ RECURSE into left side only

