from collections import deque

def first_negative_in_every_window(arr, k):
    result = []
    neg_indices = deque()
    # ① SCAN each index
    for i in range(len(arr)):
        # ② TRACK negative indices only
        if arr[i] < 0:
            neg_indices.append(i)
        if i >= k - 1:
            # ③ DROP indices that slid out on the left
            while neg_indices and neg_indices[0] <= i - k:
                neg_indices.popleft()
            # ④ RECORD front of queue as this window's answer
            result.append(arr[neg_indices[0]] if neg_indices else 0)
    return result

leetcode-239-sliding-window-maximum.answer:
from collections import deque

def max_sliding_window(nums, k):
    dq = deque()
    result = []
    for i, num in enumerate(nums):
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

geeksforgeeks-longest-k-unique-character.answer:
def longest_k_unique_substring(s, k):
    counts = {}
    left = 0
    best = -1
    # ① EXPAND window by moving right
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        # ② SHRINK while too many distinct characters
        while len(counts) > k:
            left_ch = s[left]
            counts[left_ch] -= 1
            if counts[left_ch] == 0:
                del counts[left_ch]
            left += 1  # ③ MOVE left inward
        # ④ CHECK for exactly k distinct characters
        if len(counts) == k:
            best = max(best, right - left + 1)  # ⑤ RECORD longest valid window
    return best

