def find_pivot_index(nums):
    total = sum(nums)  # ① TOTAL sum computed once
    left_sum = 0
    for i, num in enumerate(nums):
        right_sum = total - left_sum - num  # ② DERIVE right-side sum
        # ③ CHECK if left and right sums balance
        if left_sum == right_sum:
            return i
        left_sum += num  # ④ ADVANCE running left sum
    return -1  # ⑤ no pivot found

leetcode-523-continuous-subarray-sum.answer:
def check_subarray_sum(nums, k):
    remainder_index = {0: -1}  # remainder 0 seen before any elements
    prefix_sum = 0
    # ① SCAN accumulating running sum
    for i, num in enumerate(nums):
        prefix_sum += num
        remainder = prefix_sum % k  # ② REDUCE to remainder mod k
        # ③ CHECK if this remainder repeated far enough back
        if remainder in remainder_index:
            if i - remainder_index[remainder] > 1:
                return True
        else:
            remainder_index[remainder] = i  # ④ RECORD first occurrence
    return False  # ⑤ no divisible subarray found

leetcode-268-missing-number.answer:
def missing_number(nums):
    n = len(nums)
    xor_all = 0
    # ① XOR every expected value in the full range
    for i in range(n + 1):
        xor_all ^= i
    # ② XOR every value actually present, cancelling matched pairs
    for num in nums:
        xor_all ^= num
    return xor_all  # ③ only the missing number survives

