class NumMatrix:
    def __init__(self, matrix):
        rows, cols = len(matrix), len(matrix[0])
        self.prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
        # ① BUILD 2D prefix sums via inclusion-exclusion
        for i in range(rows):
            for j in range(cols):
                self.prefix[i + 1][j + 1] = (
                    matrix[i][j]
                    + self.prefix[i][j + 1]
                    + self.prefix[i + 1][j]
                    - self.prefix[i][j]
                )

    def sumRegion(self, row1, col1, row2, col2):
        # ② COMBINE bottom-right corner
        return (
            self.prefix[row2 + 1][col2 + 1]
            - self.prefix[row1][col2 + 1]  # ③ SUBTRACT rectangle above
            - self.prefix[row2 + 1][col1]  # ④ SUBTRACT rectangle to the left
            + self.prefix[row1][col1]  # ⑤ ADD BACK double-subtracted corner
        )

