def max_subarray_with_indices(nums):
    current_sum = best_sum = nums[0]
    start = end = temp_start = 0
    # ① SCAN remaining elements
    for i in range(1, len(nums)):
        # ② DECIDE: restart here or extend current run
        if nums[i] > current_sum + nums[i]:
            current_sum = nums[i]
            temp_start = i  # candidate new start
        else:
            current_sum += nums[i]
        # ③ CHECK if this is a new best sum
        if current_sum > best_sum:
            best_sum = current_sum
            start, end = temp_start, i  # ④ COMMIT boundaries
    return nums[start:end + 1], best_sum

