def max_sub_array_len(nums, k):
    seen = {0: -1}
    prefix_sum = 0
    best_len = 0
    # ① SCAN accumulating running sum
    for i, num in enumerate(nums):
        prefix_sum += num
        # ② CHECK for an earlier prefix that makes a sum-k subarray
        if prefix_sum - k in seen:
            best_len = max(best_len, i - seen[prefix_sum - k])
        # ③ RECORD only the first occurrence of this prefix sum
        if prefix_sum not in seen:
            seen[prefix_sum] = i
    return best_len

