def longest_subarray_xor(arr, k):
    seen = {0: -1}
    prefix_xor = 0
    best_len = 0
    # ① SCAN accumulating running XOR
    for i, num in enumerate(arr):
        prefix_xor ^= num
        needed = prefix_xor ^ k  # ② DERIVE the earlier prefix that would give XOR k
        # ③ CHECK if that earlier prefix was seen
        if needed in seen:
            best_len = max(best_len, i - seen[needed])
        # ④ RECORD only the first occurrence of this prefix XOR
        if prefix_xor not in seen:
            seen[prefix_xor] = i
    return best_len

leetcode-704-binary-search.answer:
def search(nums, target):
    low, high = 0, len(nums) - 1
    # ① NARROW the search range
    while low <= high:
        mid = (low + high) // 2
        # ② CHECK midpoint against target
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            low = mid + 1  # ③ DISCARD left half
        else:
            high = mid - 1  # ④ DISCARD right half
    return -1  # ⑤ target not found

