def search_range(nums, target):
    def find_bound(is_first):
        low, high = 0, len(nums) - 1
        result = -1
        # ① NARROW the search range
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                result = mid  # ② RECORD match but keep searching
                if is_first:
                    high = mid - 1  # ③ KEEP narrowing left for first occurrence
                else:
                    low = mid + 1  # ④ KEEP narrowing right for last occurrence
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return result

    return [find_bound(True), find_bound(False)]  # ⑤ combine first and last

leetcode-33-search-in-rotated-sorted-arr.answer:
def search_rotated(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        # ① CHECK midpoint against target
        if nums[mid] == target:
            return mid
        # ② DETERMINE which half is properly sorted
        if nums[low] <= nums[mid]:
            # ③ LEFT half sorted: check if target lies within it
            if nums[low] <= target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            # ④ RIGHT half sorted: check if target lies within it
            if nums[mid] < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1
    return -1  # ⑤ target not found

leetcode-1011-capacity-to-ship-packages-.answer:
def ship_within_days(weights, days):
    def feasible(capacity):
        needed_days = 1
        current_load = 0
        # ① SIMULATE loading weights day by day
        for w in weights:
            if current_load + w > capacity:
                needed_days += 1  # ② START a new day
                current_load = 0
            current_load += w
        return needed_days <= days

    low, high = max(weights), sum(weights)
    # ③ BINARY SEARCH over capacity
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid  # ④ TRY smaller capacity
        else:
            low = mid + 1  # ⑤ capacity too small, increase it
    return low

