def aggressive_cows(positions, cows):
    positions.sort()  # ① SORT so gaps can be measured in order

    def feasible(min_dist):
        placed = 1
        last_position = positions[0]
        # ② GREEDILY place items keeping min_dist apart
        for pos in positions[1:]:
            if pos - last_position >= min_dist:
                placed += 1
                last_position = pos
        return placed >= cows

    low, high = 1, positions[-1] - positions[0]
    best = 0
    # ③ BINARY SEARCH over the minimum distance
    while low <= high:
        mid = (low + high) // 2
        if feasible(mid):
            best = mid  # ④ RECORD and try a larger distance
            low = mid + 1
        else:
            high = mid - 1  # ⑤ distance too large, shrink it
    return best

