def min_eating_speed(piles, h):
    def feasible(speed):
        # ① SIMULATE total hours needed at this speed
        hours = sum(math.ceil(pile / speed) for pile in piles)
        return hours <= h

    low, high = 1, max(piles)
    # ② BINARY SEARCH over eating speed
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid  # ③ TRY a slower speed
        else:
            low = mid + 1  # ④ speed too slow, increase it
    return low

