from collections import Counter

def find_anagrams(s, p):
    m = len(p)
    if m > len(s):
        return []
    need = Counter(p)
    window = Counter(s[:m])
    result = []
    if window == need:
        result.append(0)
    for i in range(m, len(s)):
        window[s[i]] += 1
        left_char = s[i - m]
        window[left_char] -= 1
        if window[left_char] == 0:
            del window[left_char]
        if window == need:
            result.append(i - m + 1)
    return result

