from collections import Counter

def check_inclusion(pattern, s):
    need = Counter(pattern)
    window = Counter(s[:len(pattern)])  # ① INITIAL window count
    if window == need:
        return True  # ② first window already matches
    # ③ SLIDE window across the rest of s
    for right in range(len(pattern), len(s)):
        window[s[right]] += 1  # ④ ADD incoming character
        left_char = s[right - len(pattern)]
        window[left_char] -= 1  # ⑤ REMOVE outgoing character
        if window[left_char] == 0:
            del window[left_char]
        if window == need:
            return True  # ⑥ match found
    return False

