geeksforgeeks-rabin-karp-algorithm-for-p.answer:
def rabin_karp_search(text, pattern, base=256, mod=10**9 + 7):
    n, m = len(text), len(pattern)
    if m == 0 or m > n:
        return []
    high_order = pow(base, m - 1, mod)
    pattern_hash = 0
    window_hash = 0
    for i in range(m):
        pattern_hash = (pattern_hash * base + ord(pattern[i])) % mod
        window_hash = (window_hash * base + ord(text[i])) % mod
    matches = []
    for i in range(n - m + 1):
        if pattern_hash == window_hash and text[i:i + m] == pattern:
            matches.append(i)
        if i < n - m:
            window_hash = (window_hash - ord(text[i]) * high_order) % mod
            window_hash = (window_hash * base + ord(text[i + m])) % mod
            window_hash %= mod
    return matches

leetcode-187-repeated-dna-sequences.answer:
def find_repeated_substrings(s, k, base=256, mod=10**9 + 7):
    n = len(s)
    if k > n:
        return []
    high_order = pow(base, k - 1, mod)
    window_hash = 0
    # ① COMPUTE initial window hash
    for i in range(k):
        window_hash = (window_hash * base + ord(s[i])) % mod

    seen = {window_hash: [s[0:k]]}
    repeated = set()
    # ② SLIDE window, rolling the hash forward
    for i in range(1, n - k + 1):
        window_hash = (window_hash - ord(s[i - 1]) * high_order) % mod
        window_hash = (window_hash * base + ord(s[i + k - 1])) % mod
        window_hash %= mod
        substring = s[i:i + k]
        # ③ CHECK for a hash collision or genuine repeat
        if window_hash in seen:
            if substring in seen[window_hash]:
                repeated.add(substring)  # ④ CONFIRM true repeat
            else:
                seen[window_hash].append(substring)  # collision, not a repeat
        else:
            seen[window_hash] = [substring]
    return list(repeated)

