leetcode-2104-sum-of-subarray-ranges.answer:
def sub_array_ranges(nums):
    def sum_subarray_extreme(arr, find_max):
        n = len(arr)
        prev = [-1] * n
        nxt = [n] * n
        stack = []
        pop_prev = (lambda a, b: a <= b) if find_max else (lambda a, b: a >= b)
        for i in range(n):
            while stack and pop_prev(arr[stack[-1]], arr[i]):
                stack.pop()
            prev[i] = stack[-1] if stack else -1
            stack.append(i)
        stack = []
        pop_next = (lambda a, b: a < b) if find_max else (lambda a, b: a > b)
        for i in range(n - 1, -1, -1):
            while stack and pop_next(arr[stack[-1]], arr[i]):
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)
        total = 0
        for i in range(n):
            left = i - prev[i]
            right = nxt[i] - i
            total += arr[i] * left * right
        return total

    return sum_subarray_extreme(nums, True) - sum_subarray_extreme(nums, False)

