leetcode-716-max-stack.answer:
class MaxStack:
    def __init__(self):
        self.main = []
        self.track = []  # running max

    def push(self, x):
        self.main.append(x)
        # ① COMPUTE running max at this depth
        m = x if not self.track else max(x, self.track[-1])
        self.track.append(m)

    def pop(self):
        self.track.pop()
        return self.main.pop()  # ② POP both stacks together

    def top(self):
        return self.main[-1]

    def peek_max(self):
        return self.track[-1]  # ③ O(1) maximum lookup

    def pop_max(self):
        max_val = self.track[-1]
        buffer = []
        # ④ BUFFER elements above the max
        while self.main[-1] != max_val:
            buffer.append(self.pop())
        self.pop()  # ⑤ discard the max itself
        # ⑥ RESTORE buffered elements back onto the stack
        while buffer:
            self.push(buffer.pop())
        return max_val

