def calculate(s):
    def precedence(op):
        return 2 if op in '*/' else 1

    def apply_op(a, b, op):
        if op == '+': return a + b
        if op == '-': return a - b
        if op == '*': return a * b
        if op == '/': return int(a / b)

    nums, ops, i, n = [], [], 0, len(s)
    # ① SCAN the expression character by character
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        # ② PARSE a full multi-digit number
        if c.isdigit():
            val = 0
            while i < n and s[i].isdigit():
                val = val * 10 + int(s[i])
                i += 1
            nums.append(val)
            continue
        if c == '(':
            ops.append(c)  # ③ PUSH open-paren marker
        elif c == ')':
            # ④ RESOLVE until the matching '(' is found
            while ops[-1] != '(':
                b, a, op = nums.pop(), nums.pop(), ops.pop()
                nums.append(apply_op(a, b, op))
            ops.pop()
        else:
            # ⑤ APPLY higher/equal precedence operators first
            while ops and ops[-1] != '(' and precedence(ops[-1]) >= precedence(c):
                b, a, top = nums.pop(), nums.pop(), ops.pop()
                nums.append(apply_op(a, b, top))
            ops.append(c)
        i += 1
    # ⑥ DRAIN remaining operators
    while ops:
        b, a, op = nums.pop(), nums.pop(), ops.pop()
        nums.append(apply_op(a, b, op))
    return nums[-1]  # ⑦ final result

