def eval_rpn(tokens):
    stack = []
    ops = {'+', '-', '*', '/'}
    # ① SCAN tokens left to right
    for token in tokens:
        if token in ops:
            # ② POP two operands, b first since it's on top
            b = stack.pop()
            a = stack.pop()
            if token == '+': stack.append(a + b)
            elif token == '-': stack.append(a - b)
            elif token == '*': stack.append(a * b)
            else: stack.append(int(a / b))  # ③ APPLY operator and push result
        else:
            stack.append(int(token))  # ④ PUSH operand
    return stack[-1]  # ⑤ final result

