def decode_string(s):
    stack = []  # (previous_string, repeat_count)
    current = ''
    num = 0
    # ① SCAN each character
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)  # ② ACCUMULATE multi-digit count
        elif ch == '[':
            stack.append((current, num))  # ③ SAVE state before nesting deeper
            current = ''
            num = 0
        elif ch == ']':
            prev_string, repeat = stack.pop()  # ④ RESTORE outer state
            current = prev_string + current * repeat  # combine with repeated inner
        else:
            current += ch
    return current

