class TwoStackQueue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def _shift(self):
        # ① ONLY refill out_stack when it's empty
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())  # ② REVERSE order via two pops/pushes

    def enqueue(self, x):
        self.in_stack.append(x)  # ③ PUSH new value onto in_stack

    def dequeue(self):
        self._shift()
        return self.out_stack.pop()  # ④ OLDEST value comes off out_stack

    def peek_front(self):
        self._shift()
        return self.out_stack[-1]  # ⑤ OLDEST value without removing it

