leetcode-346-moving-average-from-data-st.answer:
from collections import deque

class MovingAverage:
    def __init__(self, size: int):
        self.size = size
        self.window = deque()
        self.window_sum = 0

    def next(self, val: int) -> float:
        self.window.append(val)  # ① ADD incoming value
        self.window_sum += val
        # ② EVICT oldest value once the window exceeds its fixed size
        if len(self.window) > self.size:
            self.window_sum -= self.window.popleft()
        return self.window_sum / len(self.window)  # ③ AVERAGE over current window

