    fresh_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                queue.append((r, c))
            elif grid[r][c] == 1:
                fresh_count += 1
    minutes = 0
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    while queue and fresh_count > 0:
        for _ in range(len(queue)):
