def fib(n, memo=None):
    if memo is None:
        memo = {}
    # ① CHECK cache before recomputing
    if n in memo:
        return memo[n]
    if n <= 1:
        return n  # ② base case
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)  # ③ RECURSE and CACHE result
    return memo[n]

