def max_ancestor_diff(root, cur_min=None, cur_max=None):
    if root is None:
        return 0  # ① empty subtree contributes nothing
    val, left, right = root
    # ② SEED min/max on the very first call
    if cur_min is None:
        cur_min = cur_max = val
    best = max(abs(val - cur_min), abs(val - cur_max))  # ③ COMPARE against best ancestor extremes
    new_min, new_max = min(cur_min, val), max(cur_max, val)  # ④ UPDATE running extremes
    return max(best,
                max_ancestor_diff(left, new_min, new_max),
                max_ancestor_diff(right, new_min, new_max))  # ⑤ RECURSE both children

