def is_balanced(root):
    def helper(node):
        if node is None:
            return (0, True)
        left_height, left_balanced = helper(node.left)
        right_height, right_balanced = helper(node.right)
        height = 1 + max(left_height, right_height)
        balanced = (
            left_balanced
            and right_balanced
            and abs(left_height - right_height) <= 1
