def count_unival_subtrees(root):
    count = 0

    def helper(node):
        nonlocal count
        if node is None:
            return True  # empty subtree is trivially univalue  # ① base case

        left_is_uni = helper(node.left)  # ② RECURSE children first (bottom-up)
        right_is_uni = helper(node.right)

        if not left_is_uni or not right_is_uni:
            return False  # ③ a non-univalue child breaks this subtree too

        if node.left and node.left.val != node.val:
            return False  # ④ CHECK value matches left child
        if node.right and node.right.val != node.val:
            return False  # ⑤ CHECK value matches right child

        count += 1  # ⑥ SIDE EFFECT: bump the global counter
        return True  # returned value is separate from the tracked count

    helper(root)
    return count

