def max_root_to_leaf(root):
    if root is None:
        return 0  # ① empty subtree contributes nothing
    if root.left is None and root.right is None:
        return root.val  # ② leaf case
    if root.left is None:
        return root.val + max_root_to_leaf(root.right)  # ③ only right child exists
    if root.right is None:
        return root.val + max_root_to_leaf(root.left)  # ④ only left child exists
    return root.val + max(max_root_to_leaf(root.left), max_root_to_leaf(root.right))  # ⑤ CHOOSE better branch

