def lowest_common_ancestor(root, p, q):
    current = root
    # ① DESCEND until the split point is found
    while current:
        if p.val < current.val and q.val < current.val:
            current = current.left  # ② BOTH targets on the left, keep descending
        elif p.val > current.val and q.val > current.val:
            current = current.right  # ③ BOTH targets on the right, keep descending
        else:
            # p and q are on different sides (or one equals current) - split point found
            return current  # ④ FOUND the LCA
    return None

