class Node:
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors is not None else []

def clone_graph(node):
    if not node:
        return None

    cloned = {}

    def dfs(n):
        if n in cloned:
            return cloned[n]  # ① ALREADY cloned, reuse it (handles cycles)
        copy = Node(n.val)
        cloned[n] = copy  # ② RECORD clone before recursing into neighbors
        for neighbor in n.neighbors:
            copy.neighbors.append(dfs(neighbor))  # ③ RECURSE to clone each neighbor
        return copy

    return dfs(node)

