def valid_path(n, edges, source, destination):
    graph = defaultdict(list)
    # ① BUILD undirected adjacency list
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = {source}
    stack = [source]

    # ② SIMULATE DFS with an explicit stack
    while stack:
        node = stack.pop()
        # ③ CHECK if destination reached
        if node == destination:
