def bellman_ford(num_vertices, edges, source):
    dist = [float('inf')] * num_vertices
    dist[source] = 0

    # ① RELAX all edges, up to V-1 times
    for _ in range(num_vertices - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break  # ② EARLY EXIT once distances stabilize

    # ③ CHECK for a negative cycle: one more relaxation pass
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v]:
            return None  # ④ negative cycle detected

    return dist

