        if rank[root_x] < rank[root_y]:
            root_x, root_y = root_y, root_x
        parent[root_y] = root_x  # ③ UNION by rank
        if rank[root_x] == rank[root_y]:
            rank[root_x] += 1
        return True

    edges_sorted = sorted(edges, key=lambda e: e[2])  # ④ SORT globally by weight
    mst_edges = []
    total_cost = 0

    # ⑤ GREEDILY accept cheapest edges that don't form a cycle
    for u, v, w in edges_sorted:
