def is_bipartite_dfs(v, adj):
    color = [-1] * v

    def dfs(node, c):
        color[node] = c
        for neighbor in adj[node]:
            if color[neighbor] == -1:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

    for start in range(v):
        if color[start] == -1:
            if not dfs(start, 0):
                return False
    return True

