def find_anagrams(s, p):
    result = []
    k = len(p)
    if k > len(s):
        return result  # ① pattern longer than string, no matches possible
    p_count = Counter(p)
    window_count = Counter(s[:k])  # ② INITIAL window count
    if window_count == p_count:
        result.append(0)  # ③ first window matches
    # ④ SLIDE window across the rest of the string
    for i in range(k, len(s)):
        left_char = s[i - k]
        window_count[left_char] -= 1  # ⑤ REMOVE outgoing character
        if window_count[left_char] == 0:
            del window_count[left_char]
        window_count[s[i]] += 1  # ⑥ ADD incoming character
        if window_count == p_count:
            result.append(i - k + 1)  # ⑦ RECORD matching start index
    return result

