def find_pivot_index(nums):
    total = sum(nums)  # ① TOTAL sum computed once
    left_sum = 0
    for i, num in enumerate(nums):
        right_sum = total - left_sum - num  # ② DERIVE right-side sum
        # ③ CHECK if left and right sums balance
        if left_sum == right_sum:
            return i
        left_sum += num  # ④ ADVANCE running left sum
    return -1  # ⑤ no pivot found

