def z_function(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    # ① SCAN each position after the first
    for i in range(1, n):
        # ② REUSE previous match data if inside current window
        if i < r:
            z[i] = min(r - i, z[i - l])
        # ③ EXTEND match by direct comparison
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        # ④ UPDATE window if this match reaches further right
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z

