    if not root:
        return 0

    queue = deque([(root, 1)])

    # ① PROCESS nodes in BFS order, level by level
    while queue:
        node, depth = queue.popleft()
        # ② CHECK for a leaf node
        if not node.left and not node.right:
            return depth  # ③ first leaf found is at the minimum depth
        if node.left:
            queue.append((node.left, depth + 1))  # ④ ENQUEUE children with incremented depth
        if node.right:
            queue.append((node.right, depth + 1))

    return 0

