def is_balanced(root):
    def helper(node):
        if node is None:
            return (0, True)  # (height, balanced)  # ① base case

        left_height, left_balanced = helper(node.left)  # ② RECURSE left, get both facts at once
        right_height, right_balanced = helper(node.right)  # ③ RECURSE right, get both facts at once

        height = 1 + max(left_height, right_height)  # ④ COMPUTE height from children
        balanced = (
            left_balanced
            and right_balanced
            and abs(left_height - right_height) <= 1  # ⑤ CHECK balance condition
        )

        return (height, balanced)

    return helper(root)[1]

