def is_balanced_sentinel(root):
    def height(node):
        if node is None:
            return 0  # ① base case
        left_height = height(node.left)
        if left_height == -1:
            return -1  # ② PROPAGATE imbalance sentinel immediately
        right_height = height(node.right)
        if right_height == -1:
            return -1  # ③ PROPAGATE imbalance sentinel immediately
        if abs(left_height - right_height) > 1:
            return -1  # ④ DETECT imbalance at this node
        return 1 + max(left_height, right_height)  # ⑤ RETURN real height otherwise

    return height(root) != -1  # ⑥ sentinel never escaped means it's balanced

