def num_islands(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    count = 0

    def dfs(r, c):
        # ① BASE CASE: out of bounds or not unvisited land
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != '1':
            return
        grid[r][c] = '0'  # ② MARK visited
        dfs(r+1, c)  # ③ FLOOD FILL in all 4 directions
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)

    # ④ SCAN every cell, starting a fresh DFS per new island
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                count += 1
                dfs(r, c)

    return count

