def find_redundant_edge(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # ① PATH COMPRESSION
            x = parent[x]
        return x

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return False  # ② already connected
        if rank[root_x] < rank[root_y]:
            root_x, root_y = root_y, root_x
        parent[root_y] = root_x  # ③ UNION by rank
        if rank[root_x] == rank[root_y]:
            rank[root_x] += 1
        return True

    # ④ SCAN edges in order, return the first one that creates a cycle
    for u, v in edges:
        if not union(u, v):
            return [u, v]
    return []

