def dsu_by_size(n, edges):
    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # ① PATH COMPRESSION
            x = parent[x]
        return x

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return False
        if size[root_x] < size[root_y]:
            root_x, root_y = root_y, root_x
        parent[root_y] = root_x  # ② ATTACH smaller under larger
        size[root_x] += size[root_y]  # ③ TRACK combined size directly
        return True

    # ④ UNION every edge
    for u, v in edges:
        union(u, v)

    return max(size[find(i)] for i in range(n))  # ⑤ LARGEST component size

