from collections import defaultdict

def can_finish(num_courses, prerequisites):
    graph = defaultdict(list)
    for a, b in prerequisites:
        graph[b].append(a)  # ① b must come before a

    visited = [False] * num_courses
    on_stack = [False] * num_courses

    def dfs(node):
        visited[node] = True
        on_stack[node] = True  # ② MARK node as on the current path
        for neighbor in graph[node]:
            if on_stack[neighbor]:
                return True  # ③ BACK EDGE to current path means a cycle
            if not visited[neighbor] and dfs(neighbor):
                return True
        on_stack[node] = False  # ④ CLEAR path marker when backtracking
        return False

    # ⑤ RUN dfs from every unvisited course
    for course in range(num_courses):
        if not visited[course]:
            if dfs(course):
                return False

    return True

