def topological_sort_kahn(num_vertices, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    in_degree = [0] * num_vertices
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1  # ① COUNT incoming edges

    queue = deque(v for v in range(num_vertices) if in_degree[v] == 0)  # ② SEED with zero in-degree
    order = []

    # ③ REMOVE zero in-degree vertices one at a time
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != num_vertices:
        return []  # ④ CYCLE detected: some vertices never reached in-degree 0
    return order

