        on_stack[node] = True  # ① MARK node as on current path
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
            elif on_stack[neighbor]:
                has_cycle[0] = True  # ② BACK EDGE detected
        on_stack[node] = False
        order.append(node)  # post-order: appended after all descendants are done  # ③ RECORD in post-order

