def topological_sort_dfs(num_vertices, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = [False] * num_vertices
    on_stack = [False] * num_vertices
    order = []
    has_cycle = [False]

    def dfs(node):
        visited[node] = True
        on_stack[node] = True  # ① MARK node as on current path
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
            elif on_stack[neighbor]:
                has_cycle[0] = True  # ② BACK EDGE detected
        on_stack[node] = False
        order.append(node)  # post-order: appended after all descendants are done  # ③ RECORD in post-order

    # ④ RUN dfs from every unvisited vertex
    for v in range(num_vertices):
        if not visited[v]:
            dfs(v)

    if has_cycle[0]:
        return []
    return order[::-1]  # ⑤ REVERSE post-order gives topological order

