def floyd_warshall(num_vertices, edges):
    INF = float('inf')
    dist = [[INF] * num_vertices for _ in range(num_vertices)]
    for i in range(num_vertices):
        dist[i][i] = 0  # ① distance to self is 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)  # ② SEED direct edges

    # ③ k MUST be outermost: try every vertex as an intermediate stop
    for k in range(num_vertices):
        for i in range(num_vertices):
            if dist[i][k] == INF:
                continue  # ④ SKIP if no path from i to k exists yet
            for j in range(num_vertices):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]  # ⑤ IMPROVE via intermediate k

    return dist

def floyd_warshall_with_path(num_vertices, edges):
    INF = float('inf')
    dist = [[INF] * num_vertices for _ in range(num_vertices)]
    nxt = [[None] * num_vertices for _ in range(num_vertices)]

    for i in range(num_vertices):
        dist[i][i] = 0
        nxt[i][i] = i  # ① SELF-path is trivial
    for u, v, w in edges:
        if w < dist[u][v]:
            dist[u][v] = w
            nxt[u][v] = v  # ② SEED direct edge's first hop

    # ③ SAME triple loop as standard Floyd-Warshall
    for k in range(num_vertices):
        for i in range(num_vertices):
            if dist[i][k] == INF:
                continue
            for j in range(num_vertices):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    nxt[i][j] = nxt[i][k]  # ④ REDIRECT i's first hop toward k's route

    def reconstruct_path(u, v):
        if nxt[u][v] is None:
            return []  # ⑤ no path exists
        path = [u]
        while u != v:
            u = nxt[u][v]  # ⑥ WALK forward hop by hop
            path.append(u)
        return path

    return dist, reconstruct_path

