def kruskal_mst(num_vertices, edges):
    parent = list(range(num_vertices))
    rank = [0] * num_vertices

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # ① PATH COMPRESSION
            x = parent[x]
        return x

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return False  # ② already connected: would form a cycle
        if rank[root_x] < rank[root_y]:
            root_x, root_y = root_y, root_x
        parent[root_y] = root_x  # ③ UNION by rank
        if rank[root_x] == rank[root_y]:
            rank[root_x] += 1
        return True

    edges_sorted = sorted(edges, key=lambda e: e[2])  # ④ SORT globally by weight
    mst_edges = []
    total_cost = 0

    # ⑤ GREEDILY accept cheapest edges that don't form a cycle
    for u, v, w in edges_sorted:
        if union(u, v):
            mst_edges.append((u, v, w))
            total_cost += w
            if len(mst_edges) == num_vertices - 1:
                break

    return mst_edges, total_cost

def min_bottleneck_to_connect(num_vertices, edges):
    parent = list(range(num_vertices))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # ① PATH COMPRESSION
            x = parent[x]
        return x

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return False
        parent[root_y] = root_x
        return True

    edges_sorted = sorted(edges, key=lambda e: e[2])  # ② SORT globally by weight
    components = num_vertices
    bottleneck = 0

    # ③ GREEDILY connect components with increasing edge weights
    for u, v, w in edges_sorted:
        if union(u, v):
            bottleneck = w  # ④ LAST accepted edge's weight is the answer
            components -= 1
            if components == 1:
                break

    return bottleneck if components == 1 else -1  # ⑤ CHECK graph fully connected

