def is_bipartite(num_vertices, graph):
    from collections import deque

    color = [-1] * num_vertices

    # ① CHECK every component separately
    for start in range(num_vertices):
        if color[start] != -1:
            continue
        color[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if color[neighbor] == -1:
                    color[neighbor] = 1 - color[node]  # ② ASSIGN opposite color
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False  # ③ SAME color neighbor: not bipartite

    return True

