from collections import deque

def zero_one_bfs(num_vertices, graph, source):
    dist = [float('inf')] * num_vertices
    dist[source] = 0
    dq = deque([source])

    # ① PROCESS deque front to back, front always has smallest distance
    while dq:
        node = dq.popleft()
        for neighbor, weight in graph[node]:
            new_dist = dist[node] + weight
            # ② RELAX edge if it improves the neighbor's distance
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                if weight == 0:
                    dq.appendleft(neighbor)  # ③ ZERO-weight: push to front
                else:
                    dq.append(neighbor)  # ④ ONE-weight: push to back

    return dist

leetcode-239-sliding-window-maximum::sli.answer:
from collections import deque

def max_sliding_window(nums, k):
    dq = deque()  # stores indices, values decreasing front to back
    result = []
    # ① SCAN each index and value
    for i, num in enumerate(nums):
        # ② POP smaller values off the back, they can't be the max now
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)  # ③ ADD current index
        if dq[0] <= i - k:
            dq.popleft()  # ④ front has slid out of the window
        if i >= k - 1:
            result.append(nums[dq[0]])  # ⑤ RECORD current window's max
    return result

leetcode-103-binary-tree-zigzag-level-or.answer:
from collections import deque
from typing import List, Optional

def zigzagLevelOrder(root: Optional['TreeNode']) -> List[List[int]]:
    if not root:
        return []
    result = []
    queue = deque([root])
    left_to_right = True
    # ① PROCESS one level at a time
    while queue:
        level_size = len(queue)
        level_values = deque()
        for _ in range(level_size):
            node = queue.popleft()
            # ② APPEND to front or back depending on direction
            if left_to_right:
                level_values.append(node.val)
            else:
                level_values.appendleft(node.val)
            if node.left:
                queue.append(node.left)  # ③ ENQUEUE children unchanged by direction
            if node.right:
                queue.append(node.right)
        result.append(list(level_values))
        left_to_right = not left_to_right  # ④ FLIP direction for next level
    return result

